begin;
create extension if not exists pgtap with schema extensions;
set local search_path=extensions,public,api,private,auth;
select no_plan();
\ir fixtures/final-result-release-setup.sql
select ok(not has_function_privilege('authenticated','api.svc_result_query_runtime_configure_v2(uuid,uuid,text,text,boolean,text)','execute'),'browser cannot configure admitted reader or storage target');
select ok(not has_function_privilege('service_role','api.qry_final_result_release_probe_v2(uuid,text,uuid,uuid,text)','execute'),'storage service credential cannot impersonate a manager probe');
select ok(not has_table_privilege('service_role','private.final_result_query_runtime_head','update'),'runtime head has no raw service update path');
select is((select count(*) from pg_class where oid in ('private.final_result_query_runtime_head'::regclass,'private.final_result_query_runtime_revisions'::regclass) and relrowsecurity),2::bigint,'both runtime relations have RLS');
set local role service_role;
select is(api.svc_result_query_runtime_read_v2()->'data','null'::jsonb,'no runtime is admitted by migration');
select throws_ok($q$select api.svc_result_query_runtime_configure_v2('87940000-0000-4000-8000-000000000001',null,repeat('d',64),repeat('c',64),true,repeat(' ',5000)||'reason')$q$,'22023','Invalid final Result runtime admission','raw reason size is bounded before trim');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.role','authenticated',true);
select set_config('request.jwt.claim.sub','87930000-0000-4000-8000-000000000001',true);
select api.cmd_final_result_release_prepare_v2(pg_temp.final_release_plan(),'synthetic-runtime');
select is(api.qry_final_result_release_probe_page_v2('87930000-0000-4000-8000-000000000010',pg_temp.final_plan_hash())->>'code','final_result_selection_unsealed','unsealed scope cannot use private probes');
select api.cmd_final_result_release_members_v2('87930000-0000-4000-8000-000000000010',pg_temp.final_plan_hash(),'[{"uuid":"87920000-0000-4000-8000-000000000010","version":"01.00.000"},{"uuid":"87920000-0000-4000-8000-000000000012","version":"01.00.000"}]');
select api.cmd_final_result_release_seal_v2('87930000-0000-4000-8000-000000000010',pg_temp.final_plan_hash());
select is(api.qry_final_result_release_probe_page_v2('87930000-0000-4000-8000-000000000010',pg_temp.final_plan_hash())->>'code','final_result_runtime_unavailable','sealed storage evidence alone is not runtime admission');
reset role;
set local role service_role;
select is(api.svc_result_query_runtime_configure_v2('87940000-0000-4000-8000-000000000001',null,repeat('d',64),repeat('c',64),true,'synthetic reader')#>>'{data,isCurrent}','true','explicit initial reader revision is current');
select is(api.svc_result_query_runtime_configure_v2('87940000-0000-4000-8000-000000000001',null,repeat('d',64),repeat('c',64),true,'synthetic reader')#>>'{data,runtimeRevision}','87940000-0000-4000-8000-000000000001','exact lost-ACK retry recovers original runtime');
select throws_ok($q$select api.svc_result_query_runtime_configure_v2('87940000-0000-4000-8000-000000000001',null,repeat('d',64),repeat('e',64),true,'synthetic reader')$q$,'23505','Final Result runtime revision identity conflict','same revision cannot bind another reader');
select is(api.svc_result_query_runtime_configure_v2('87940000-0000-4000-8000-000000000099',null,repeat('d',64),repeat('c',64),true,'stale expected') ->>'code','runtime_revision_conflict','stale expected head cannot replace runtime');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','87930000-0000-4000-8000-000000000002',true);
select is(api.qry_final_result_release_probe_page_v2('87930000-0000-4000-8000-000000000010',pg_temp.final_plan_hash())->>'code','not_data_product_manager','ordinary user cannot discover staging artifacts');
select set_config('request.jwt.claim.sub','87930000-0000-4000-8000-000000000001',true);
select is(jsonb_array_length(api.qry_final_result_release_probe_page_v2('87930000-0000-4000-8000-000000000010',pg_temp.final_plan_hash())#>'{data,artifacts}'),2,'bounded page includes both selected artifacts');
select is(api.qry_final_result_release_probe_page_v2('87930000-0000-4000-8000-000000000010',pg_temp.final_plan_hash())#>>'{data,artifacts,0,probes,0,uuid}','87920000-0000-4000-8000-000000000010','first artifact probes selected direct Result only');
select is(api.qry_final_result_release_probe_page_v2('87930000-0000-4000-8000-000000000010',pg_temp.final_plan_hash())#>>'{data,artifacts,1,probes,0,uuid}','87920000-0000-4000-8000-000000000012','derived Result gets its own artifact probe without parent selection');
select is(jsonb_array_length(api.qry_final_result_release_probe_page_v2('87930000-0000-4000-8000-000000000010',pg_temp.final_plan_hash())#>'{data,artifacts,0,probes}'),1,'single selected row is not duplicated as first and last');
select is(api.qry_final_result_release_probe_page_v2('87930000-0000-4000-8000-000000000010',pg_temp.final_plan_hash(),null,null,1)#>>'{data,nextArtifactCursor}','87920000-0000-4000-8000-000000000001','artifact pagination returns exact last included cursor');
select is(api.qry_final_result_release_probe_page_v2('87930000-0000-4000-8000-000000000010',pg_temp.final_plan_hash(),'87940000-0000-4000-8000-000000000001','87920000-0000-4000-8000-000000000001',1)#>'{data,nextArtifactCursor}','null'::jsonb,'second page terminates without skipping second artifact');
select throws_ok($q$select api.qry_final_result_release_probe_page_v2('87930000-0000-4000-8000-000000000010',pg_temp.final_plan_hash(),null,'87920000-0000-4000-8000-000000000001',1)$q$,'22023','Invalid bounded final Result probe page','continuation must bind a runtime revision');
select throws_ok($q$select api.qry_final_result_release_probe_page_v2('87930000-0000-4000-8000-000000000010',pg_temp.final_plan_hash(),null,null,101)$q$,'22023','Invalid bounded final Result probe page','artifact page count is bounded');
select is(api.qry_final_result_release_probe_v2('87930000-0000-4000-8000-000000000010',pg_temp.final_plan_hash(),'87940000-0000-4000-8000-000000000001','87920000-0000-4000-8000-000000000010','01.00.000')#>>'{data,scope,kind}','readiness','selected result uses unpublished readiness scope, not public resolver');
select is(api.qry_final_result_release_probe_v2('87930000-0000-4000-8000-000000000010',pg_temp.final_plan_hash(),'87940000-0000-4000-8000-000000000001','87920000-0000-4000-8000-000000000011','01.00.000')->>'code','final_result_probe_not_available','file-contained unselected Result remains denied');
select is(api.qry_final_result_release_probe_v2('87930000-0000-4000-8000-000000000010',pg_temp.final_plan_hash(),'87940000-0000-4000-8000-000000000001','87920000-0000-4000-8000-000000000030','01.00.000')->>'code','final_result_probe_not_available','source Unit cannot stand in for exact Result probe');
select is(api.qry_final_result_release_probe_v2('87930000-0000-4000-8000-000000000010',pg_temp.final_plan_hash(),null,'87920000-0000-4000-8000-000000000010','01.00.000')->>'code','runtime_revision_conflict','numeric probe must bind exact runtime');
reset role;
create temporary table original_permission as select private.final_result_release_probe_context('87930000-0000-4000-8000-000000000010',pg_temp.final_plan_hash())#>>'{data,permissionHash}' value;
set local role service_role;
select api.svc_result_query_runtime_configure_v2('87940000-0000-4000-8000-000000000002','87940000-0000-4000-8000-000000000001',repeat('d',64),repeat('c',64),false,'disable synthetic');
reset role;
set local role authenticated;
select is(api.qry_final_result_release_probe_page_v2('87930000-0000-4000-8000-000000000010',pg_temp.final_plan_hash())->>'code','final_result_runtime_unavailable','disabled admission blocks private probing');
reset role;
set local role service_role;
select is(api.svc_result_query_runtime_configure_v2('87940000-0000-4000-8000-000000000001',null,repeat('d',64),repeat('c',64),true,'synthetic reader')#>>'{data,isCurrent}','false','old revision retry does not re-enable or resurrect history');
select is(api.svc_result_query_runtime_read_v2()#>>'{data,runtimeRevision}','87940000-0000-4000-8000-000000000002','historical retry preserves current runtime');
select api.svc_result_query_runtime_configure_v2('87940000-0000-4000-8000-000000000003','87940000-0000-4000-8000-000000000002',repeat('d',64),repeat('c',64),true,'re-enable with new revision');
reset role;
set local role authenticated;
select is(api.qry_final_result_release_probe_page_v2('87930000-0000-4000-8000-000000000010',pg_temp.final_plan_hash(),'87940000-0000-4000-8000-000000000001')->>'code','runtime_revision_conflict','returning to identical settings still invalidates older probe revision');
select is(api.qry_final_result_release_probe_v2('87930000-0000-4000-8000-000000000010',pg_temp.final_plan_hash(),'87940000-0000-4000-8000-000000000003','87920000-0000-4000-8000-000000000012','01.00.000')#>>'{data,result,uuid}','87920000-0000-4000-8000-000000000012','fresh exact runtime admits selected derived Result');
reset role;
set local role service_role;
select api.svc_result_query_runtime_configure_v2('87940000-0000-4000-8000-000000000004','87940000-0000-4000-8000-000000000003',repeat('e',64),repeat('c',64),true,'different storage target');
reset role;
set local role authenticated;
select is(api.qry_final_result_release_probe_page_v2('87930000-0000-4000-8000-000000000010',pg_temp.final_plan_hash())->>'code','final_result_runtime_unavailable','admitted reader cannot silently use a different Candidate storage target');
reset role;
set local role service_role;
select api.svc_result_query_runtime_configure_v2('87940000-0000-4000-8000-000000000005','87940000-0000-4000-8000-000000000004',repeat('d',64),repeat('c',64),true,'restore exact target with a new revision');
reset role;
select throws_ok($q$update private.final_result_query_runtime_revisions set enabled=true where id='87940000-0000-4000-8000-000000000002'$q$,'55000','Result query evidence is immutable','runtime admission history cannot be rewritten');
delete from private.roles where user_id='87930000-0000-4000-8000-000000000001' and team_id='00000000-0000-0000-0000-000000000000';
set local role authenticated;
select is(api.qry_final_result_release_probe_page_v2('87930000-0000-4000-8000-000000000010',pg_temp.final_plan_hash())->>'code','not_data_product_manager','every page rechecks live actor role');
reset role;
insert into private.roles(user_id,team_id,role,created_at) values('87930000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000000','data_product_manager',clock_timestamp()+interval '1 second');
select isnt(private.final_result_release_probe_context('87930000-0000-4000-8000-000000000010',pg_temp.final_plan_hash())#>>'{data,permissionHash}',(select value from original_permission),'re-admission changes permission precondition even for the same manager UUID');
create function pg_temp.all_selected_plan() returns text language sql as $$
 select pg_temp.final_release_plan('{"releaseRunId":"87930000-0000-4000-8000-000000000011","releaseVersion":"2026.11.2","selectionCount":3,"selectionHash":"402fe6857b36ec20ac91b65c3de19973d2b0fc8fd284df7c8deb09bae89a017e"}')
$$;
grant execute on function pg_temp.all_selected_plan() to authenticated;
set local role authenticated;
select api.cmd_final_result_release_prepare_v2(pg_temp.all_selected_plan(),'all-selected-probe');
select api.cmd_final_result_release_members_v2('87930000-0000-4000-8000-000000000011',encode(extensions.digest(convert_to(pg_temp.all_selected_plan(),'UTF8'),'sha256'),'hex'),'[{"uuid":"87920000-0000-4000-8000-000000000010","version":"01.00.000"},{"uuid":"87920000-0000-4000-8000-000000000011","version":"01.00.000"},{"uuid":"87920000-0000-4000-8000-000000000012","version":"01.00.000"}]');
select api.cmd_final_result_release_seal_v2('87930000-0000-4000-8000-000000000011',encode(extensions.digest(convert_to(pg_temp.all_selected_plan(),'UTF8'),'sha256'),'hex'));
select is(jsonb_array_length(api.qry_final_result_release_probe_page_v2('87930000-0000-4000-8000-000000000011',encode(extensions.digest(convert_to(pg_temp.all_selected_plan(),'UTF8'),'sha256'),'hex'))#>'{data,artifacts,0,probes}'),2,'multiple selected rows retain distinct first and last probes');
select is(api.qry_final_result_release_probe_page_v2('87930000-0000-4000-8000-000000000011',encode(extensions.digest(convert_to(pg_temp.all_selected_plan(),'UTF8'),'sha256'),'hex'))#>>'{data,artifacts,0,probes,1,uuid}','87920000-0000-4000-8000-000000000011','last probe is exact selected Result rather than a source or ordinal');
reset role;
select is((select status from private.lca_release_runs where id='87930000-0000-4000-8000-000000000010'),'prepared','describing probes does not claim successful numeric validation');
select is((select count(*) from private.lca_release_publications),0::bigint,'runtime/probe metadata does not publish');
select * from finish();
rollback;
